use hog4pilot::{venue::{Venue,Answer},project::Store};
#[test]fn full_24_fixture_workflow(){let mut v=Venue::demo();assert_eq!(v.fixtures.len(),24);for i in 0..24{assert_eq!(v.identify().is_ok(),i<21);v.answer("mount",Some(format!("Софит {}",i%6))).unwrap();v.answer("position",None).unwrap();v.answer("role",Some("Wash".into())).unwrap();v.answer("coverage",if i<21{Some("Сцена".into())}else{None}).unwrap();v.next().unwrap();}assert_eq!(v.cursor,24);assert_eq!(v.groups()[0].fixtures.len(),21);let ids=v.groups().remove(0).fixtures;let frame=v.frame(&ids,0.6,[1.0,0.65,0.3]).unwrap();assert_eq!(frame[0],153);assert!(frame[84..].iter().all(|x|*x==0));let store=Store::open(std::path::Path::new(":memory:")).unwrap();store.save_venue(&v).unwrap();let recovered=store.load_venue().unwrap().unwrap();assert_eq!(recovered.cursor,24);assert_eq!(recovered.fixtures[0].position,Answer::Unknown);}
#[test]fn all_unknown_can_finish(){let mut v=Venue::demo();for _ in 0..24{assert!(v.next().is_err());for field in ["mount","position","role","coverage"]{v.answer(field,None).unwrap();}v.next().unwrap();}assert!(v.groups().is_empty());}
#[test]fn no_hazer_or_unknown_output(){let v=Venue::demo();for i in 21..24{assert!(v.frame(&[v.fixtures[i].id.clone()],1.0,[1.0;3]).is_err());}let mut forged=v.clone();forged.fixtures[23].verified=true;assert!(forged.identify().is_err());}
